bytes4 constant GT_ZKP_RELEASE = 0x53a1eb85;
// The "prp grant type" for the "distributing" ZKPs
// bytes4(keccak256("panther-zkp-distribute"))
bytes4 constant GT_ZKP_DISTRIBUTE = 0xd48cb9c0;
// The "prp grant type" for the "distributing" ZKPs
